export function createStudy({getState,getLanguage,translate,escape,sourceButton}){
 let deck=[],position=0,revealed=false,activeState='',marks={};
 const text=(en,ka)=>getLanguage()==='ka'?ka:en;
 const load=()=>{try{marks=JSON.parse(localStorage.getItem('road-ready-cards-'+getState().id)||'{}')||{};}catch{marks={};}};
 function open(topic='',review=false){const {id,config}=getState();activeState=id;load();deck=config.questions.filter(q=>(!topic||q.topic===topic)&&(!review||marks[q.id]!=='known'));position=0;revealed=false;}
 function action(value){if(value==='flip'){revealed=!revealed;return;}if(!revealed||!deck[position])return;marks[deck[position].id]=value==='known'?'known':'review';try{localStorage.setItem('road-ready-cards-'+activeState,JSON.stringify(marks));}catch{}position++;revealed=false;}
 function cards(){const {id}=getState();if(id!==activeState)open();const raw=deck[position];if(!raw)return `<section class="study-hero"><h1 tabindex="-1">${text('Deck complete!','ბარათები დასრულებულია!')}</h1><p>${text('Your review choices are saved on this device.','თქვენი არჩევანი შენახულია ამ მოწყობილობაზე.')}</p><button data-view="guide">${text('Back to study guide','სახელმძღვანელოზე დაბრუნება')}</button></section>`;const q=translate(raw);return `<div class="row"><button class="quiet" data-view="guide">← ${text('Study guide','სახელმძღვანელო')}</button><span>${position+1} / ${deck.length} · ${escape(q.topic)}</span></div><progress class="progress" value="${position}" max="${deck.length}" aria-label="${text('Deck progress','პროგრესი')}"></progress><article class="flashcard"><p class="eyebrow">${text(revealed?'THE ANSWER':'THINK IT THROUGH',revealed?'პასუხი':'დაფიქრდით')}</p>${q.image?`<img class="sign" src="${escape(q.image)}" alt="${text('Road sign','საგზაო ნიშანი')}">`:'<span class="study-symbol" aria-hidden="true">🚙</span>'}<h1 tabindex="-1">${escape(q.question)}</h1>${revealed?`<div class="study-answer" role="status"><h2>${escape(q.options[q.answer])}</h2><p>${escape(q.explanation)}</p>${sourceButton(q.page)}</div>`:''}<button class="primary" data-card="flip" aria-expanded="${revealed}">${text(revealed?'Hide answer':'Reveal answer',revealed?'პასუხის დამალვა':'პასუხის ნახვა')}</button>${revealed?`<div class="row card-rating"><button class="secondary" data-card="review">${text('Review again','კვლავ გასამეორებელი')}</button><button class="primary" data-card="known">✓ ${text('Got it','გასაგებია')}</button></div>`:''}</article>`;}
 function guide(t){const {config}=getState();load();const known=config.questions.filter(q=>marks[q.id]==='known').length;return `<section class="study-hero"><div><p class="eyebrow">${t(config.name)} · ${text('LEARN YOUR WAY','ისწავლეთ თქვენებურად')}</p><h1 tabindex="-1">${text('Small lessons. Big confidence.','მცირე გაკვეთილები. მეტი თავდაჯერება.')}</h1><p>${text('Explore a topic, learn the rule, then test your memory.','აირჩიეთ თემა, ისწავლეთ წესი და შეამოწმეთ მეხსიერება.')}</p><div class="row"><button class="primary" data-deck="">${text('Start flashcards','ბარათებით სწავლა')} →</button><button class="secondary" data-deck="" data-review="yes">${text('Review remaining','დარჩენილის გამეორება')}</button></div><p>${known} / ${config.questions.length} ${text('cards learned','ბარათი ნასწავლია')}</p></div><div class="study-signs" aria-hidden="true">${['two-way','slippery','hospital'].map(s=>`<img src="./signs/${s}.png" alt="">`).join('')}</div></section><h2>${text('Explore your topics','შეისწავლეთ თემები')}</h2><div class="study-grid">${config.topics.map((topic,i)=>{const qs=config.questions.filter(q=>q.topic===topic),q=translate(qs.find(q=>q.image)||qs[0]);return `<article class="study-topic tone-${i%4}"><div class="study-topic-top">${q.image?`<img src="${escape(q.image)}" alt="${text('Road sign','საგზაო ნიშანი')}">`:`<span aria-hidden="true">${['📘','🚦','🛣️','🚙'][i%4]}</span>`}<span>${qs.length} ${text('cards','ბარათი')}</span></div><h3>${t(topic)}</h3><details><summary>${text('Remember this','დაიმახსოვრეთ')}</summary><p>${escape(q.explanation)}</p>${sourceButton(q.page)}</details><button class="secondary" data-deck="${escape(topic)}">${text('Study flashcards','სასწავლო ბარათები')} →</button></article>`;}).join('')}</div><h2>${text('Go deeper: your state manual','მეტი ინფორმაცია: შტატის სახელმძღვანელო')}</h2><div class="topic-grid">${config.chapters.map(([title,page])=>`<button class="topic" data-page="${page}"><div>${t(title)}<span>${t('Manual page {n}',{n:page})}</span></div>→</button>`).join('')}</div><p class="notice">${t('These are original study questions for the basic automobile knowledge test. They do not reproduce the official exam and are not a complete substitute for reading the manual. This app uses the manual you supplied; it does not automatically update when laws change.')}</p>`;}
 return {open,action,cards,guide};
}
